    n = int(input[0])
    a = list(map(int, input[1:(n + 1) // 2 + 1]))
    x = int(input[(n + 1) // 2 + 1])

    prefix_sum = [0]
    for i in range(len(a)):
        prefix_sum.append(prefix_sum[-1] + a[i])

    def check_k(k):
        for i in range(n - k + 1):
            if i < len(a) - k + 1:
                if prefix_sum[i + k] - prefix_sum[i] + x * (k - (len(a) - i)) <= 0:
                    return False
            else:
                if (prefix_sum[-1] - prefix_sum[i]) + x * k <= 0:
                    return False
        return True

    left, right = 1, n
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if check_k(mid):
            result = mid
            left = mid + 1
        else:
            right = mid - 1

